# ── Public API ───────────────────────────────────────────────────────────────

def _resources(bundle_or_resources: Any) -> Iterable[Dict]:
    if isinstance(bundle_or_resources, dict) and bundle_or_resources.get("resourceType") == "Bundle":
        for entry in bundle_or_resources.get("entry", []):
            if entry.get("resource"):
                yield entry["resource"]
    elif isinstance(bundle_or_resources, dict):
        yield bundle_or_resources
    else:
        yield from bundle_or_resources


def _full_url_map(bundle_or_resources: Any) -> Dict[str, str]:
    """Resolve only unambiguous Bundle aliases; never let entry order choose a patient."""
    full_urls: Dict[str, str] = {}
    if isinstance(bundle_or_resources, dict) and bundle_or_resources.get("resourceType") == "Bundle":
        entries = bundle_or_resources.get("entry", [])
        if not isinstance(entries, list):
            raise ValueError("Invalid FHIR Bundle entries")
        for entry in entries:
            if not isinstance(entry, dict) or not isinstance(entry.get("resource"), dict):
                raise ValueError("Invalid FHIR Bundle resource")
            r = entry["resource"]
            alias = entry.get("fullUrl")
            if alias is not None and not isinstance(alias, str):
                raise ValueError("Invalid FHIR Bundle alias")
            if alias and r.get("resourceType") and r.get("id"):
                target = f"{r['resourceType']}/{r['id']}"
                if alias in full_urls and full_urls[alias] != target:
                    raise ValueError("Conflicting FHIR Bundle aliases; human review required")
                full_urls[alias] = target
    return full_urls


def resolved_resources(bundle_or_resources: Any) -> List[Dict]:
    """Independent resources with Bundle fullUrl references canonicalised.

    Validate before snapshots or loop-store mutation. Errors contain no input values.
    This does not infer identities for unresolved urns or identifier-only references.
    """
    import copy
    full_urls = _full_url_map(bundle_or_resources)
    if isinstance(bundle_or_resources, dict):
        resources = list(_resources(bundle_or_resources))
    elif isinstance(bundle_or_resources, (list, tuple)):
        resources = list(bundle_or_resources)
    else:
        raise ValueError("Expected FHIR resources or a Bundle")
    for resource in resources:
        if (not isinstance(resource, dict) or not isinstance(resource.get("resourceType"), str)
                or not re.fullmatch(r"[A-Z][A-Za-z0-9]+", resource["resourceType"])
                or not isinstance(resource.get("id"), str)
                or not re.fullmatch(r"[A-Za-z0-9\-.]{1,64}", resource["id"])):
            raise ValueError("Invalid FHIR resource identity")
    resources = copy.deepcopy(resources)
    def resolve(node):
        if isinstance(node, dict):
            ref = node.get("reference")
            if isinstance(ref, str) and ref in full_urls:
                node["reference"] = full_urls[ref]
            for value in node.values():
                resolve(value)
        elif isinstance(node, list):
            for value in node:
                resolve(value)
    resolve(resources)
    return resources


def _with_full_urls(bundle_or_resources: Any, fn):
    """Run fn() with an unambiguous Bundle fullUrl → Type/id map."""
    token = _FULL_URLS.set(_full_url_map(bundle_or_resources))
    try:
        return fn()
    finally:
        _FULL_URLS.reset(token)


def bundle_to_events(bundle_or_resources: Any, evaluation_time: Any = None) -> Tuple[Dict[str, List[Dict]], List[str]]:
    # Mappers, context, and version handling make multiple passes over resources.
    if not isinstance(bundle_or_resources, (dict, list, tuple)):
        bundle_or_resources = list(bundle_or_resources)
    return _with_full_urls(bundle_or_resources, lambda: _bundle_to_events(bundle_or_resources, evaluation_time))


# ── report versions ──────────────────────────────────────────────────────────
# A preliminary report and the final report of the same study can arrive as two DiagnosticReport
# resources with different ids. Read separately, they open the same obligation twice. A draft
# version (preliminary / partial / registered) is replaced by a released version of the same
# report: same patient, same study (accession number, else the same orders) and same report code.
# Released versions never replace each other: a separate addendum resource may hold only the
# addendum text, and dropping the original would lose its findings.
REPORT_DRAFT_STATUSES = {"preliminary", "partial", "registered"}
_REPORT_RELEASED_STATUSES = {"final", "amended", "corrected", "appended"}


def _report_identity(r: Dict) -> Optional[str]:
    for i in r.get("identifier", []):
        types = {c.get("code") for c in (i.get("type") or {}).get("coding", [])}
        if i.get("value") and ("ACSN" in types or "accession" in str(i.get("system") or "").lower()):
            return f"accession:{i.get('system') or ''}|{i['value']}"
    orders = sorted(filter(None, (_ref_id(b, "ServiceRequest") for b in r.get("basedOn", []))))
    return "orders:" + ",".join(orders) if orders else None


def _report_code(r: Dict) -> str:
    codes = sorted(_codes(r.get("code")))
    return ",".join(codes) if codes else _concept_text(r.get("code")).strip().lower()


_RESULT_DRAFT_STATUSES = {"registered", "preliminary"}
_RESULT_RELEASED_STATUSES = {"final", "amended", "corrected"}


def _result_identity(r: Dict) -> Optional[str]:
    """One lab result sent as several Observation resources (preliminary, then final): same code, same
    collection time and, when given, the same specimen or order. Without a collection time two
    resources cannot be matched safely, so both are kept."""
    when = _first(r.get("effectiveDateTime"), (r.get("effectivePeriod") or {}).get("start"), r.get("effectiveInstant"))
    code = _report_code(r)
    if not when or not code:
        return None
    specimen = _ref_id(r.get("specimen") or {}, "Specimen") or ""
    orders = ",".join(sorted(filter(None, (_ref_id(b, "ServiceRequest") for b in r.get("basedOn", [])))))
    try:
        when = normalize_timestamp(when).isoformat()
    except (TypeError, ValueError):
        return None
    return f"{code}|{when}|{specimen}|{orders}"


def _superseded_reports() -> Dict[str, str]:
    """Draft versions replaced by a released version: reports (accession number or orders, and report
    code) and, the same way, lab results (code, collection time, specimen or order). Released versions
    never replace each other: an addendum or a correction may carry only part of the content."""
    groups: Dict[Tuple, List[Dict]] = defaultdict(list)
    for r in _CURRENT_RESOURCES.get():
        rtype, pid = r.get("resourceType"), _patient_id(r)
        if not r.get("id") or not pid:
            continue
        if rtype == "DiagnosticReport":
            ident = _report_identity(r)
            if ident:
                groups[(rtype, pid, ident, _report_code(r))].append(r)
        elif rtype == "Observation":
            ident = _result_identity(r)
            if ident:
                groups[(rtype, pid, ident)].append(r)
    out: Dict[str, str] = {}
    for (rtype, *_), versions in groups.items():
        draft, released_set = ((REPORT_DRAFT_STATUSES, _REPORT_RELEASED_STATUSES) if rtype == "DiagnosticReport"
                               else (_RESULT_DRAFT_STATUSES, _RESULT_RELEASED_STATUSES))
        released = [r for r in versions if str(r.get("status", "")).lower() in released_set]
        if not released:
            continue
        def release_instant(resource):
            value = _first(resource.get("issued"), resource.get("effectiveDateTime"),
                           (resource.get("meta") or {}).get("lastUpdated"))
            try:
                return normalize_timestamp(value)
            except (ValueError, TypeError):
                return None
        instants = [release_instant(r) for r in released]
        # Ambiguous ordering cannot establish which released record supersedes
        # a draft. Keep the draft visible for human reconciliation.
        if any(instant is None for instant in instants):
            continue
        newest = released[max(range(len(released)), key=lambda i: instants[i])]
        for r in versions:
            if str(r.get("status", "")).lower() in draft and r["id"] != newest["id"]:
                out[f"{rtype}/{r['id']}"] = f"{rtype}/{newest['id']}"
    return out


_CURRENT_RESOURCES: "contextvars.ContextVar[List[Dict]]" = contextvars.ContextVar("clinloop_resources", default=[])


def superseded_reports(bundle_or_resources: Any) -> Dict[str, str]:
    """Draft report versions replaced by a released version of the same report: {old source: new source}.
    The loop store uses this to retire loops an earlier version opened (LoopStore.supersede_sources)."""
    resources = list(_resources(bundle_or_resources))

    def run():
        token = _CURRENT_RESOURCES.set(resources)
        try:
            return _superseded_reports()
        finally:
            _CURRENT_RESOURCES.reset(token)
    return _with_full_urls(bundle_or_resources, run)


def _bundle_to_events(bundle_or_resources: Any, evaluation_time: Any = None) -> Tuple[Dict[str, List[Dict]], List[str]]:
    """
    Convert FHIR resources into ClinLoop events grouped by patient.

    Returns (events_by_patient, warnings). Resources that cannot be mapped
    (unsupported type, no patient, no timestamp) are skipped with a warning
    rather than silently dropped.
    """
    by_patient: Dict[str, List[Dict]] = defaultdict(list)
    warnings: List[str] = []
    uncertain_status_count = 0
    patients = _patient_context(bundle_or_resources, warnings)
    resources = list(_resources(bundle_or_resources))
    token = _CURRENT_RESOURCES.set(resources)
    try:
        superseded = _superseded_reports()
    finally:
        _CURRENT_RESOURCES.reset(token)

    for r in resources:
        rtype = r.get("resourceType", "?")
        rid = r.get("id", "?")
        if f"{rtype}/{rid}" in superseded:    # the released version of this report is read instead
            continue
        mapper = MAPPERS.get(rtype)
        explicit = _explicit_event_type(r)
        if mapper is None and not explicit:
            continue
        pid = _patient_id(r)
        if not pid:
            warnings.append("FHIR resource: no patient reference; skipped")
            continue
        status = _status(r)
        if status == "entered-in-error":
            continue
        try:
            mapped = mapper(r) if mapper else []
        except Exception as e:      # one malformed resource must not stop every other patient's monitoring
            warnings.append(f"FHIR resource: could not be read ({type(e).__name__}); skipped")
            continue
        if explicit:
            ts = mapped[0][1] if mapped else _first(
                r.get("effectiveDateTime"), r.get("issued"), r.get("authoredOn"), r.get("sent"),
                r.get("start"), r.get("performedDateTime"))
            base = mapped[0][2] if mapped else {}
            mapped = [(explicit, ts, {**base, "mapping": [f"explicit extension→{explicit}"]})]
        if mapped and status == "unknown":
            # Count only: never echo resource IDs, source status strings or report text.
            uncertain_status_count += 1
        for etype, ts, details in mapped:
            if not ts:
                if "FHIR resource: no timestamp; skipped" not in warnings:
                    warnings.append("FHIR resource: no timestamp; skipped")
                continue
            try:
                normalize_timestamp(ts)
            except (ValueError, TypeError):   # "10/01/2026": skipped with a warning, the rest of the feed goes on
                if "FHIR resource: unreadable date; skipped" not in warnings:
                    warnings.append("FHIR resource: unreadable date; skipped")
                continue
            # Deterministic id: the same resource yields the same loop key on
            # every ingest, whatever order the bundle lists resources in.
            suffix = details.pop("event_suffix", None)   # several plans from one note
            by_patient[pid].append({
                "event_id": f"{rtype}/{rid}:{etype}" + (f":{suffix}" if suffix else ""),
                "patient_id": pid,
                "event_type": etype,
                "timestamp": ts,
                "details": details,
                "status": (("completed" if etype in REQUEST_EVENT_TYPES else "ordered")
                           if rtype == "ServiceRequest" and status in ("ordered", "completed") else status),
                "source": f"{rtype}/{rid}",
            })

    if uncertain_status_count:
        warnings.append(f"{uncertain_status_count} mapped resources have missing or unrecognised status; "
                        "completion requires human review")

    # A feed whose numeric results carry neither an interpretation code nor a reference range
    # cannot raise abnormal-result alerts at all: say so instead of looking reassuringly quiet
    numeric = [e for evs in by_patient.values() for e in evs
               if e["event_type"] == EventType.LAB_RESULT.value and isinstance(e["details"].get("value"), (int, float))]
    if len(numeric) >= UNFLAGGED_LABS_WARN_AT and not any(e["details"].get("flag") for e in numeric) \
            and not any(r.get("interpretation") or r.get("referenceRange") for r in _resources(bundle_or_resources)
                        if r.get("resourceType") == "Observation"):
        warnings.append(f"{len(numeric)} numeric lab results carry no interpretation flag and no reference range: "
                        "abnormal-result rules (R001, R002, R021, R022) cannot fire for them; ask the laboratory "
                        "interface to send OBX-8 / Observation.interpretation or reference ranges")

    for pid, events in by_patient.items():
        # PACS indexes and DICOM headers can describe the same study differently.
        # Retain each observation with stable provenance, but none may prove a
        # completed follow-up until the conflicting study metadata is reconciled.
        # Other duplicate identities still fail the graph's strict collision guard.
        import hashlib
        import json
        study_groups = defaultdict(list)
        for event in events:
            if event["source"].startswith("ImagingStudy/"):
                study_groups[event["event_id"]].append(event)
        for group in study_groups.values():
            variants = {json.dumps(e, sort_keys=True, default=str): e for e in group}
            if len(variants) < 2:
                continue
            for event in group:
                encoded = json.dumps(event, sort_keys=True, default=str)
                event["event_id"] += ":variant:" + hashlib.sha256(encoded.encode()).hexdigest()
                event["status"] = "unknown"
                event["details"]["review_note_all"] = "Conflicting imaging study records; human reconciliation required"
            message = "Conflicting imaging study records retained for review; excluded from completion evidence"
            if message not in warnings:
                warnings.append(message)
        _derive_context(events)
        decide_obligations(events, patients.get(pid, {}))
        # Patterns that depend on "now" (age reached by today) use the evaluation time, not the wall clock
        apply_patterns(events, {**patients.get(pid, {}), "evaluation_time": evaluation_time})
        apply_ai_review(events)
    return dict(by_patient), warnings


def _patient_context(bundle_or_resources: Any, warnings: Optional[List[str]] = None) -> Dict[str, Dict[str, Any]]:
    """Birth date and administrative sex per patient (for age- and sex-specific radiology guidance)."""
    out: Dict[str, Dict[str, Any]] = {}
    for r in _resources(bundle_or_resources):
        if r.get("resourceType") != "Patient" or not r.get("id"):
            continue
        ctx: Dict[str, Any] = {}
        birth = str(r.get("birthDate", ""))
        m = re.fullmatch(r"(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?", birth)
        try:
            if m:
                ctx["birth_date"] = datetime(int(m.group(1)), int(m.group(2) or 7), int(m.group(3) or 1))
            elif birth:
                raise ValueError
        except ValueError:
            message = "Patient birth date is invalid; age-dependent rules require human review"
            if warnings is not None and message not in warnings:
                warnings.append(message)
        if r.get("gender"):
            ctx["sex"] = str(r["gender"]).lower()
        out[r["id"]] = ctx
    return out


def _derive_context(events: List[Dict]) -> None:
    """
    Add facts that need more than one resource:
      * results finalised after the patient's latest prior discharge
        (R006 positive culture callback, R021 abnormal-result review);
      * drug-specific monitoring labs after a medication change (R010).
    """
    def ts(e):
        return normalize_timestamp(e["timestamp"])

    discharges = sorted(ts(e) for e in events if e["event_type"] == EventType.DISCHARGE.value
                        and is_fulfilling_status(e.get("status"), e.get("event_type")))

    # Liver imaging in a patient with HCC risk is surveillance, and starts the next interval
    risk_since = min((ts(e) for e in events if e["event_type"] == EventType.DIAGNOSIS.value
                      and e["details"].get("hcc_risk")
                      and is_fulfilling_status(e.get("status"), e.get("event_type"))), default=None)
    if risk_since is not None:
        for e in events:
            if e["event_type"] == EventType.LIVER_IMAGING.value and ts(e) >= risk_since \
                    and is_fulfilling_status(e.get("status"), e.get("event_type")):
                e["details"]["hcc_surveillance"] = True
    _merge_ed_into_admission(events, ts)
    stays = [(normalize_timestamp(e["details"]["arrived_at"]) - timedelta(hours=12), ts(e)) for e in events
             if e["event_type"] == EventType.DISCHARGE.value and e["details"].get("arrived_at")
             and is_fulfilling_status(e.get("status"), e.get("event_type"))]
    # An "outpatient" encounter lasting over a day is a stay in practice (mislabelled admissions are common)
    stays += [(ts(e), normalize_timestamp(e["details"]["period_end"])) for e in events
              if e["event_type"] == EventType.FOLLOWUP_APPOINTMENT.value and e["details"].get("period_end")
              and is_fulfilling_status(e.get("status"), e.get("event_type"))
              and normalize_timestamp(e["details"]["period_end"]) - ts(e) > timedelta(hours=24)]
    _mark_inpatient_starts(events, ts, stays)
    for e in events:          # results taken in hospital: the team at the bedside acts on them (motifs use this too)
        if e["event_type"] == EventType.LAB_RESULT.value and any(start <= ts(e) <= end for start, end in stays):
            e["details"]["in_stay"] = True
    _group_abnormal_results(events, ts, stays)
    _mark_renewals(events, ts)
    _mark_known_heart_failure(events, ts)
    _mark_guideline_context(events, ts)
    _mark_hdp_deliveries(events, ts)
    med_changes = [e for e in events if e["event_type"] == EventType.MEDICATION_CHANGE.value
                   and e["details"].get("condition") == "requires_monitoring"]
    derived: List[Dict] = []

    for e in events:
        if e["event_type"] not in (EventType.LAB_RESULT.value, EventType.CULTURE_RESULT.value):
            continue
        t = ts(e)
        # A result pending at discharge (Roy 2005): drawn by the time of discharge, resulted after it. When the
        # feed gives both times that is checked exactly; otherwise a result within 7 days of discharge is taken
        # as pending, and later ones are ordinary outpatient results (R001/R002)
        d_ = e["details"]
        if d_.get("collected") and d_.get("issued"):
            drawn, resulted = normalize_timestamp(d_["collected"]), normalize_timestamp(d_["issued"])
            prior = [d for d in discharges if drawn <= d < resulted]
        else:
            resulted = t
            prior = [d for d in discharges if d < t and (t - d).days <= 7]
        if prior and not any(start <= resulted <= end for start, end in stays):   # not back in hospital by then
            e["details"]["resulted_after_discharge"] = True
            if e["event_type"] == EventType.CULTURE_RESULT.value and e["details"].get("result") == "positive":
                e["details"].setdefault("condition", "positive_post_discharge")

        loinc = set(e["details"].get("loinc", []))
        analyte = e["details"].get("analyte")
        for med in med_changes:
            drug = med["details"].get("drug")
            if (loinc & DRUG_MONITORING_LOINC.get(drug, set()) or analyte in _MONITORING_ANALYTES.get(drug, set())) \
                    and ts(med) < t:
                derived.append({
                    **{k: v for k, v in e.items() if k != "details"},
                    "event_id": f"{e['source']}:followup_lab",
                    "event_type": EventType.FOLLOWUP_LAB.value,
                    "details": {"drug": drug, "analyte": analyte, "mapping": [f"{drug} monitoring lab→followup_lab"]},
                })
                break
    events.extend(derived)


_MONITORING_ANALYTES = {label: analytes for label, _, analytes, _ in DRUG_MONITORING}

# Numeric results without any flag or range, from which the feed is reported as unable to flag abnormal results
UNFLAGGED_LABS_WARN_AT = 20

# A prescription for the same drug and dose within this many days of the previous one is a renewal
RENEWAL_DAYS = 400
_HEART_FAILURE = re.compile(r"heart[ _]failure|\bchf\b|\bhfref\b|\bhfpef\b|심부전", re.I)


def _product(text: str) -> str:
    """The drug and form without its strength ('lisinopril oral tablet'), to compare doses of one product."""
    t = re.sub(r"\d+(?:\.\d+)?\s*(?:mg|mcg|µg|ug|g|ml|unt|units?|meq|%)?(?:/\s*(?:ml|mg|actuat|hr))?\b", " ", text.lower())
    return " ".join(t.split())


def _strength_mg(text: str) -> Optional[float]:
    m = re.search(r"(\d+(?:\.\d+)?)\s*mg\b", text or "", re.I)
    return float(m.group(1)) if m else None


def _mark_renewals(events: List[Dict], ts) -> None:
    """
    A renewal is not a medication change. EHRs write a new prescription for every refill or
    annual renewal; only a new drug, a restart after a long gap, or a new dose makes monitoring
    labs (R010) or an INR recheck due.
    """
    last: Dict[Tuple[str, str, str], datetime] = {}
    meds = [e for e in events if e["event_type"] == EventType.MEDICATION_CHANGE.value and e["details"].get("drug")]
    for e in sorted(meds, key=ts):
        d = e["details"]
        key = (d["drug"], d.get("medication") or "", d.get("dose") or "")
        prev, last[key] = last.get(key), ts(e)
        if prev is not None and (ts(e) - prev).days <= RENEWAL_DAYS and d.get("condition"):
            d.pop("condition")
            d["renewal"] = True
            d["mapping"] = d.get("mapping", []) + [
                f"same {d['drug']} and dose as {prev.date()}: renewal, no new monitoring due"]
            continue
        # A lower strength of a drug already taken is a dose reduction: monitoring labs are for starts and
        # increases (an anticoagulant's INR is due after any change, so it is not exempt)
        if d.get("condition") == "requires_monitoring":
            strength = _strength_mg(d.get("medication") or "")
            product = _product(d.get("medication") or "")
            earlier = [_strength_mg(k[1]) for k, t in last.items()        # the same product and form only
                       if k[0] == d["drug"] and k != key and _product(k[1]) == product
                       and (ts(e) - t).days <= RENEWAL_DAYS]
            if strength is not None and earlier and all(x is not None and x > strength for x in earlier):
                d.pop("condition")
                d["dose_reduction"] = True
                d["mapping"] = d.get("mapping", []) + [f"{d['drug']} dose reduced: no new monitoring due"]


# An abnormal result of the same test in the same direction within this many days is a known abnormality
KNOWN_ABNORMAL_DAYS = 90


# Results that are indices or descriptive parts of a panel: shown with the panel, never a review of their own
_PANEL_INDEX = re.compile(r"\bmchc?\b|\bmcv\b|\brdw\b|anion gap|eosinophil|basophil|monocyte|lymphocyte|"
                          r"neutrophil|granulocyte|hyaline|\bcasts?\b|epithelial|bacteria\b|yeast|crystals|"
                          r"\bmpv\b|nrbc|reticulocyte|specific gravity|urobilinogen|\bph\b", re.I)
# A value this close to the reference limit (fraction of the limit) is borderline, not a new review
BORDERLINE_FRACTION = 0.10


def _minor_abnormality(d: Dict) -> Optional[str]:
    """Why an out-of-range result is not worth a review of its own, or None."""
    if _PANEL_INDEX.search(str(d.get("test") or "")):
        return "a panel index, reviewed with its panel"
    value, low, high = d.get("value"), d.get("ref_low"), d.get("ref_high")
    if isinstance(value, (int, float)):
        if isinstance(high, (int, float)) and high > 0 and high < value <= high * (1 + BORDERLINE_FRACTION):
            return f"borderline ({value} vs upper limit {high})"
        if isinstance(low, (int, float)) and low > 0 and low * (1 - BORDERLINE_FRACTION) <= value < low:
            return f"borderline ({value} vs lower limit {low})"
    return None


def _mark_inpatient_starts(events: List[Dict], ts, stays) -> None:
    """A drug started during a hospital stay is monitored there daily: R010 is for outpatient starts."""
    for e in events:
        d = e["details"]
        if e["event_type"] == EventType.MEDICATION_CHANGE.value and d.get("condition") == "requires_monitoring" \
                and any(start <= ts(e) <= end for start, end in stays):
            d.pop("condition")
            d["started_in_hospital"] = True
            d.setdefault("mapping", []).append("started during a hospital stay: monitored there, no R010")


def _group_abnormal_results(events: List[Dict], ts, stays) -> None:
    """
    Which abnormal (not critical) results open a "review and tell the patient" obligation (R001, R002, R021):
      * not one taken during a hospital or ED stay: the team at the bedside acts on it;
      * one review per blood draw: the abnormal results of one sample become one obligation, listed on it;
      * not a known abnormality: the same test abnormal in the same direction within 90 days.
    Critical values are never held back (R022 applies everywhere).
    """
    labs = sorted((e for e in events if e["event_type"] == EventType.LAB_RESULT.value
                   and e["details"].get("flag") in ("HIGH", "LOW", "ABNORMAL")), key=ts)
    last_abnormal: Dict[Tuple[str, str], datetime] = {}
    draws: Dict[datetime, Dict] = {}
    for e in labs:
        d, t = e["details"], ts(e)
        key = (str(d.get("analyte") or d.get("test") or "").lower(), d["flag"])
        resulted = normalize_timestamp(d["issued"]) if d.get("issued") else t
        if any(start <= t <= end and resulted <= end for start, end in stays):
            # Handled at the bedside; it does not make a later outpatient result "already known".
            # (Drawn in hospital but resulted after discharge is the pending-result case, R021: kept.)
            d["abnormal_handled"] = "taken during a hospital stay"
            d.setdefault("mapping", []).append(f"abnormal result not a new review: {d['abnormal_handled']}")
            continue
        minor = _minor_abnormality(d)
        if minor:
            d["abnormal_handled"] = minor
            d.setdefault("mapping", []).append(f"abnormal result not a new review: {minor}")
            continue
        prev = last_abnormal.get(key)
        last_abnormal[key] = t
        if prev is not None and t - prev <= timedelta(days=KNOWN_ABNORMAL_DAYS):
            d["abnormal_handled"] = f"known abnormal since {prev.date()}"
        elif t in draws:
            first = draws[t]
            first["details"].setdefault("panel_abnormal", []).append(
                f"{d.get('test')} {d.get('value', '')} {d.get('unit') or ''} ({d['flag'].lower()})".strip())
            d["abnormal_handled"] = f"reviewed with {first['details'].get('test')} from the same sample"
        else:
            draws[t] = e
            continue
        d.setdefault("mapping", []).append(f"abnormal result not a new review: {d['abnormal_handled']}")


def _merge_ed_into_admission(events: List[Dict], ts) -> None:
    """
    An emergency visit that ends in admission is one stay, not two discharges: the patient leaves the ED
    for a ward, not for home. Its discharge is dropped when an inpatient stay began during the ED visit
    or within 12 hours of it (otherwise post-discharge rules such as R014 and R023 would fire twice).
    """
    stays = [e for e in events if e["event_type"] == EventType.DISCHARGE.value and e["details"].get("arrived_at")
             and is_fulfilling_status(e.get("status"), e.get("event_type"))]
    drop = []
    for e in stays:
        start, end = normalize_timestamp(e["details"]["arrived_at"]), ts(e)
        # Another stay began during this one (or within 12 hours of its end) and lasted longer: the patient
        # moved on (ED → ward, or two overlapping encounters for one admission); only the last end is a discharge
        if any(x is not e and start <= normalize_timestamp(x["details"]["arrived_at"]) <= end + timedelta(hours=12)
               and ts(x) > end for x in stays):
            drop.append(e)
    for e in drop:
        events.remove(e)


def _mark_hdp_deliveries(events: List[Dict], ts) -> None:
    """A delivery stay in a woman diagnosed with a hypertensive disorder of this pregnancy: postpartum BP check (R024)."""
    hdp = [(ts(e), str(e["details"].get("diagnosis", ""))) for e in events
           if e["event_type"] == EventType.DIAGNOSIS.value and _HDP.search(str(e["details"].get("diagnosis", "")))]
    for e in events:
        d = e["details"]
        if e["event_type"] != EventType.DISCHARGE.value or not d.get("obstetric"):
            continue
        found = [txt for t, txt in hdp if timedelta(0) <= ts(e) - t <= timedelta(days=300)]
        if found:
            d["extra_conditions"] = list(d.get("extra_conditions") or []) + ["hypertensive_disorder_pregnancy"]
            if any(_HDP_SEVERE.search(x) for x in found):
                d["severe_hypertension"] = True
            d.setdefault("mapping", []).append(f"delivery after '{found[-1]}' → postpartum BP check")


def _mark_known_heart_failure(events: List[Dict], ts) -> None:
    """A heart-failure admission in a patient already known to have heart failure is not a new diagnosis (R016)."""
    known = sorted([ts(e) for e in events if e["event_type"] == EventType.DIAGNOSIS.value
                    and _HEART_FAILURE.search(str(e["details"].get("diagnosis", "")))]
                   + [ts(e) for e in events if e["event_type"] == EventType.DISCHARGE.value
                      and _HEART_FAILURE.search(str(e["details"].get("primary_diagnosis", "")))])
    for e in events:
        if e["event_type"] != EventType.DISCHARGE.value \
                or not _HEART_FAILURE.search(str(e["details"].get("primary_diagnosis", ""))):
            continue
        # Known before this stay: "acute on chronic" / "chronic" heart failure, an earlier HF discharge,
        # or an HF diagnosis over 30 days before
        t = ts(e)
        if "chronic" in str(e["details"].get("primary_diagnosis", "")).lower() or \
                any(k < t - timedelta(days=30) for k in known) or \
                any(x["event_type"] == EventType.DISCHARGE.value and ts(x) < t and x is not e
                    and _HEART_FAILURE.search(str(x["details"].get("primary_diagnosis", ""))) for x in events):
            e["details"]["known_heart_failure"] = True
            e["details"].setdefault("mapping", []).append("heart failure known before this stay: not a new diagnosis")


# Exposure, prophylaxis or a test being ruled out is not a diagnosis
_NOT_A_DIAGNOSIS = re.compile(r"exposure|exposed|contact|prophyla|\bPrEP\b|\bPEP\b|screening|at risk|risk of|rule out|\br/o\b|"
                              r"suspected|vaccinat|immuni[sz]|노출|예방|선별|의심", re.I)
_KNOWN_HIV = re.compile(r"\bhiv\b|human immunodeficiency|\baids\b|에이즈|인체\s*면역\s*결핍", re.I)
_KNOWN_HBV = re.compile(r"hepatitis b|\bhbv\b|chronic hepatitis b|b형\s*간염", re.I)
_KNOWN_LV_DYSFUNCTION = re.compile(r"heart failure|\bhfr?ef\b|\bchf\b|cardiomyopath|ventricular (?:systolic )?dysfunction|"
                                   r"심부전|심근\s*병증|좌심실\s*기능\s*(?:저하|부전)", re.I)


def _mark_guideline_context(events: List[Dict], ts) -> None:
    """
    Context for R060, R061, R063 and R065, which needs more than one resource:
      * a reactive HIV screen or a positive HBsAg in a patient already diagnosed is not new (R060, R061);
      * an LVEF ≤ 40 % in a patient with known heart failure, cardiomyopathy or an earlier low EF is not new (R065);
      * one colonoscopy: its endoscopy and pathology reports open one surveillance obligation, dated at the
        colonoscopy, with the shortest interval (R063).
    """
    diagnoses = [(ts(e), str(e["details"].get("diagnosis", ""))) for e in events
                 if e["event_type"] == EventType.DIAGNOSIS.value and e["timestamp"]]
    hf_discharges = [ts(e) for e in events if e["event_type"] == EventType.DISCHARGE.value
                     and _HEART_FAILURE.search(str(e["details"].get("primary_diagnosis", "")))]
    for e in events:
        d = e["details"]
        cond = d.get("condition")
        if e["event_type"] == EventType.LAB_RESULT.value and cond in ("hiv_screen_reactive", "hbsag_positive"):
            known = _KNOWN_HIV if cond == "hiv_screen_reactive" else _KNOWN_HBV
            if any(t <= ts(e) and known.search(text) and not _NOT_A_DIAGNOSIS.search(text) for t, text in diagnoses):
                d.pop("condition", None)
                d.setdefault("mapping", []).append("already diagnosed (problem list): not a new result to act on")
        if e["event_type"] == EventType.ECHOCARDIOGRAM.value and "reduced_ejection_fraction" in (d.get("extra_conditions") or []):
            t = ts(e)
            earlier_low_ef = any(x is not e and x["event_type"] == EventType.ECHOCARDIOGRAM.value and ts(x) < t
                                 and isinstance(x["details"].get("lvef"), (int, float)) and x["details"]["lvef"] <= 40
                                 for x in events)
            if earlier_low_ef or any(k <= t for k in hf_discharges) or \
                    any(k <= t and _KNOWN_LV_DYSFUNCTION.search(text) for k, text in diagnoses):
                d["extra_conditions"] = [c for c in d["extra_conditions"] if c != "reduced_ejection_fraction"]
                d.setdefault("mapping", []).append("reduced EF already known (heart failure / cardiomyopathy / earlier echo): R065 not opened")

    # One colonoscopy, one surveillance obligation
    findings = sorted((e for e in events if e["event_type"] == EventType.COLONOSCOPY_FINDING.value
                       and e["details"].get("condition") == "colonoscopy_surveillance"), key=ts)
    scopes = sorted(ts(e) for e in events if e["event_type"] == EventType.COLONOSCOPY.value and e["timestamp"])
    groups: List[List[Dict]] = []
    for f in findings:
        if groups and ts(f) - ts(groups[-1][0]) <= timedelta(days=30):
            groups[-1].append(f)
        else:
            groups.append([f])
    for group in groups:
        first = ts(group[0])
        index = [t for t in scopes if first - timedelta(days=30) <= t <= first]
        keep = min(group, key=lambda f: f["details"]["rule_deadline_days"]["R063"])
        # Cancer found on any report of this colonoscopy: the cancer pathway applies, not surveillance
        if any(x["event_type"] == EventType.PATHOLOGY_RESULT.value and x["details"].get("colon_cancer")
               and first - timedelta(days=1) <= ts(x) <= first + timedelta(days=30) for x in events):
            for f in group:
                f["details"].pop("condition", None)
                f["details"].setdefault("mapping", []).append("cancer on the pathology of this colonoscopy: cancer pathway (R009)")
            continue
        for f in group:
            if f is not keep:
                f["details"].pop("condition", None)
                f["details"].setdefault("mapping", []).append("same colonoscopy as another report: one obligation")
        reasons = [str(f["details"].get("evidence_span")) for f in group if f["details"].get("evidence_span")]
        keep["details"]["evidence_span"] = "; ".join(dict.fromkeys(reasons))
        anchor = index[0] if index else first
        if anchor != ts(keep):
            keep["timestamp"] = anchor.isoformat()
            keep["details"].setdefault("mapping", []).append(f"interval counted from the colonoscopy on {anchor.date()}")


def patient_names(resources: List[Dict], patient_id: str) -> List[str]:
    """The patient's own name forms, to remove them from text sent to a model."""
    names: List[str] = []
    for r in resources:
        if r.get("resourceType") != "Patient" or r.get("id") != patient_id:
            continue
        for n in r.get("name", []):
            given = list(n.get("given") or [])
            family = n.get("family") or ""
            names += [n.get("text") or "", family, *given, " ".join(given + [family]).strip(),
                      (family + "".join(given)).strip(), (family + " " + " ".join(given)).strip()]
    return [x for x in dict.fromkeys(names) if x and len(x) >= 2]


def patient_strata(bundle_or_resources: Any, as_of: Optional[datetime] = None) -> Dict[str, Dict[str, str]]:
    """
    Equity strata from Patient resources: decade age group, preferred
    language and sex. Used only to stratify the open-loop rate (never to
    rank patients). Names, addresses and identifiers are not read.
    """
    as_of = as_of or datetime.now()
    strata: Dict[str, Dict[str, str]] = {}
    for r in _resources(bundle_or_resources):
        if r.get("resourceType") != "Patient" or not r.get("id"):
            continue
        s: Dict[str, str] = {}
        birth = str(r.get("birthDate", ""))
        if re.match(r"^\d{4}", birth):
            age = as_of.year - int(birth[:4])
            s["age_group"] = "80+" if age >= 80 else f"{(age // 10) * 10}s"
        for comm in r.get("communication", []):
            lang = _codes(comm.get("language")) or {_concept_text(comm.get("language"))}
            if lang:
                s["language"] = sorted(lang)[0]
                if comm.get("preferred"):
                    break
        if r.get("gender"):
            s["sex"] = r["gender"]
        strata[r["id"]] = s
    return strata

